@login_required
@require_POST
def move_wagtail_page_view(request, page_id):
    page = get_object_or_404(Page, id=page_id)
    target_parent_id = request.POST.get('target_parent_id')
    target_parent = get_object_or_404(Page, id=target_parent_id)
    source_perms = page.permissions_for_user(request.user)
    target_perms = target_parent.permissions_for_user(request.user)
    if not source_perms.can_move():
        raise PermissionDenied("You cannot move this page.")
    if not target_perms.can_add_subpage():
        raise PermissionDenied("You do not have permission to add pages to the destination section.")
    page.move(target_parent, pos='last-child')
    return JsonResponse({'status': 'moved', 'page_id': page.id, 'new_parent_id': target_parent.id})
